import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the downstream pricing service.
const prices = { A: 10, B: 25, C: 0.1, D: 33.33, E: 100, F: 100.01 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalOf = async (items) => (await (await post({ items })).json()).total

test('POST /orders creates an order with the summed total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const body = await res.json()
  assert.deepEqual(body, { id: body.id, items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }], total: 45 })
  assert.equal(typeof body.id, 'string')
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('no discount at exactly 100 (threshold is strictly greater than)', async () => {
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100)
})

test('10% discount above 100, then floored', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99)   // 110 -> 99
  assert.equal(await totalOf([{ sku: 'A', qty: 15 }]), 135)  // 150 -> 135
  assert.equal(await totalOf([{ sku: 'A', qty: 100 }]), 900) // 1000 -> 900
})

test('just above the threshold the discounted total drops below 100', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 100.01 costs 90, while 100 costs 100 (cliff, not a tiered discount)
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 90)
})

test('totals are floored, not rounded, to whole euros', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — Math.floor drops cents: 33.33*2=66.66 -> 66, 33.33*4=133.32*0.9=119.988 -> 119
  assert.equal(await totalOf([{ sku: 'D', qty: 2 }]), 66)
  assert.equal(await totalOf([{ sku: 'D', qty: 4 }]), 119)
})

test('floating point rounding can shift the floored total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — binary floats: 0.1*3 = 0.30000000000000004 is floored to 0; 0.1*1000 is 100 so no discount
  assert.equal(await totalOf([{ sku: 'C', qty: 3 }]), 0)
  assert.equal(await totalOf([{ sku: 'C', qty: 1000 }]), 100)
  assert.equal(await totalOf([{ sku: 'C', qty: 1001 }]), 90)
})

test('unknown sku or missing qty yields a null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN is serialised as null and the order is still created with 201
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
  assert.equal(await totalOf([{ sku: 'A' }]), null)
})

test('POST /orders rejects missing, empty, non-array items and invalid JSON with 400', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'A' }), await post(null, '{not json')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for an unknown id is 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is answered with status 200, not 404
  const res = await fetch(`${base}/orders/999999`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods are 404', async () => {
  for (const [method, path] of [['GET', '/nope'], ['DELETE', '/orders/1'], ['GET', '/orders'], ['PUT', '/orders']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
